style.css:
@-moz-document domain("youtube.com") {
/* Selecciona el logo de YouTube */
    #logo-icon {
        filter: hue-rotate(180deg); /* Cambia el color al azul */
    }
    
    /* Opcional: Cambia el texto del logo (si es visible) */
    #logo-icon-container {
        color: blue !important; /* Cambia el color del texto del logo */
    }
}
